prompt.text:
Repair the complete CommonJS source below. It must export `trimToBudget(weights, budget)` directly with `module.exports`. `weights` must be an array of non-negative finite numbers and `budget` a non-negative finite number. Starting with the entire array, repeatedly remove the larger of the two endpoint weights until the retained total is at most the budget. On equal endpoints, remove the right endpoint. Return `{ start, end, total, removed }`, where `start` is inclusive, `end` is exclusive, and `removed` lists `{ index, weight }` in removal order. For an empty array return `{ start: 0, end: 0, total: 0, removed: [] }`. Floating-point totals within `Number.EPSILON * max(1, originalTotal)` of the budget count as within budget. Preserve ordering, do not mutate the input, and throw `TypeError` for malformed values. Return a corrected complete source file.

```javascript
'use strict';

function trimToBudget(weights, budget) {
  if (!Array.isArray(weights) || typeof budget !== 'number' ||
      !Number.isFinite(budget) || budget < 0) {
    throw new TypeError('invalid input');
  }
  for (const weight of weights) {
    if (typeof weight !== 'number' || !Number.isFinite(weight) || weight < 0) {
      throw new TypeError('weights must be non-negative finite numbers');
    }
  }

  let start = 0;
  let end = weights.length;
  let total = weights.reduce((sum, weight) => sum + weight, 0);
  if (!Number.isFinite(total)) throw new TypeError('weight total must be finite');
  const tolerance = Number.EPSILON * Math.max(1, total);
  const removed = [];

  while (start < end && total - budget > tolerance) {
    if (weights[start] >= weights[end - 1]) {
      removed.push({ index: start, weight: weights[start] });
      total -= weights[start++];
    } else {
      --end;
      removed.push({ index: end, weight: weights[end] });
      total -= weights[end];
    }
  }

  return { start, end, total, removed };
}

module.exports = trimToBudget;
```

