'use strict';
const assert = require('node:assert/strict');
const trimToBudget = require('./solution');

assert.equal(typeof trimToBudget, 'function');
assert.deepEqual(trimToBudget([], 0), { start: 0, end: 0, total: 0, removed: [] });
assert.deepEqual(trimToBudget([1, 2, 3], 6), { start: 0, end: 3, total: 6, removed: [] });
assert.deepEqual(trimToBudget([5, 1, 4, 2], 5), {
  start: 1, end: 3, total: 5,
  removed: [{ index: 0, weight: 5 }, { index: 3, weight: 2 }]
});

// Equal endpoints remove the right endpoint.
assert.deepEqual(trimToBudget([4, 1, 4], 5), {
  start: 0, end: 2, total: 5, removed: [{ index: 2, weight: 4 }]
});
assert.deepEqual(trimToBudget([2, 2], 0), {
  start: 0, end: 0, total: 0,
  removed: [{ index: 1, weight: 2 }, { index: 0, weight: 2 }]
});

// The original-total tolerance makes the usual 0.1 + 0.2 rounding excess acceptable.
const tolerant = trimToBudget([0.1, 0.2], 0.3);
assert.equal(tolerant.start, 0);
assert.equal(tolerant.end, 2);
assert.equal(tolerant.removed.length, 0);
assert.equal(tolerant.total, 0.1 + 0.2);

const weights = [3, 1, 2];
const snapshot = weights.slice();
const result = trimToBudget(weights, 2);
assert.deepEqual(weights, snapshot);
assert.notEqual(result.removed, weights);
assert.deepEqual(result, {
  start: 1, end: 2, total: 1,
  removed: [{ index: 0, weight: 3 }, { index: 2, weight: 2 }]
});

for (const badWeights of [null, {}, 'x', [1, -1], [NaN], [Infinity], ['1']]) {
  assert.throws(() => trimToBudget(badWeights, 1), TypeError);
}
const sparse = new Array(1);
assert.throws(() => trimToBudget(sparse, 1), TypeError);
for (const badBudget of [-1, NaN, Infinity, '1', null]) {
  assert.throws(() => trimToBudget([], badBudget), TypeError);
}
assert.throws(() => trimToBudget([Number.MAX_VALUE, Number.MAX_VALUE], Number.MAX_VALUE), TypeError);

